const BASE_URL = "{{BASE_URL}}";
const API_KEY = "{{API_KEY}}";
const jobId = "job_3f9c2a7e5b8d4c1fa0e6b2d9c7f41a58";

// 浏览器原生 EventSource 无法携带 Authorization 头，这里用 fetch 读取流
const resp = await fetch(`${BASE_URL}/v1/jobs/${jobId}/events`, {
  headers: { Authorization: `Bearer ${API_KEY}` },
});
if (!resp.ok) throw new Error(JSON.stringify(await resp.json()));

const reader = resp.body.pipeThrough(new TextDecoderStream()).getReader();
let buffer = "";
for (;;) {
  const { value, done } = await reader.read();
  if (done) break;
  buffer += value;
  let sep;
  while ((sep = buffer.indexOf("\n\n")) !== -1) {
    const raw = buffer.slice(0, sep);
    buffer = buffer.slice(sep + 2);
    const event = raw.match(/^event: (.*)$/m)?.[1];
    const data = JSON.parse(raw.match(/^data: (.*)$/m)?.[1] ?? "{}");
    console.log(event, data.node, data.status);
  }
}

